-- Photos de matchs seniors récupérées sur la page Facebook du club (12/10/2026) : Senior A (amical contre US Varades) et Senior B (contre FC Vay Marsac, 20/09).
select string_agg(r || ':' || n, '  ') as bilan from (select case when club then 'club' else array_to_string(equipes, '+') end r, count(*) n from public.pub_photos group by 1 order by 1) x;
